	// seqsBase += 24 * seqIndex
	ADD R2<<1, R2, R10
	LSL $0x03, R10, R10
	ADD R10, R0, R0

	// outBase += outPosition
	ADD  R6, R3, R3
	MOVD R3, R19
	MOVD R3, R22
	SUB  R6, R22, R22
	MOVD R22, R21
