	CMP  R21, R12
	BHS  prefetch_in_out_0
	ADD  R22, R12, R12

prefetch_in_out_0:
	PRFM (R12), PLDL1KEEP
	PRFM 64(R12), PLDL1KEEP
	MOVD 8(R0), R10
	ADD  R10, R19, R19

prefetch_skip_0:
	ADD  $24, R0, R11
