	MOVD R6, 104(R0)
	MOVD 80(R0), R16
	SUB  R16, R5, R5
	MOVD R5, 112(R0)
	RET

empty_seqs:
	// Return value
	MOVD $0x01, R16
	MOVB R16, ret+8(FP)
	RET

// func sequenceDecs_executeSimple_safe_amd64(ctx *executeAsmContext) bool
// Requires: MMX+, SSE
TEXT ·sequenceDecs_executeSimple_safe_arm64(SB), $32-9
	MOVD ctx+0(FP), R9
	MOVD 8(R9), R1
	TST  R1, R1
	BEQ  empty_seqs
	MOVD (R9), R0

	// seqsEnd = seqsBase + 24 * len(seqs) if ctx.prefetch, else seqsBase (prefetch off)
	MOVD  R0, R20
	MOVBU 128(R9), R10
	TST   R10, R10
	BEQ   prefetch_off
	ADD   R1<<1, R1, R20
	LSL   $0x03, R20, R20
	ADD   R0, R20, R20

prefetch_off:
	MOVD 24(R9), R2
	MOVD 32(R9), R3
	MOVD 80(R9), R5
	MOVD 104(R9), R6
	MOVD 120(R9), R7
	MOVD 56(R9), R8
	MOVD 64(R9), R9
	ADD  R9, R8, R8

	// seqsBase += 24 * seqIndex
	ADD R2<<1, R2, R10
	LSL $0x03, R10, R10
	ADD R10, R0, R0

	// outBase += outPosition
	ADD  R6, R3, R3
	MOVD R3, R19
	MOVD R3, R22
	SUB  R6, R22, R22
	MOVD R22, R21
	NEG  R22, R22
	ADD  R8, R22, R22

	// Prime the prefetch window
	MOVD R0, R11
	CMP  R20, R11
	BHS  prefetch_skip_0
	MOVD (R0), R10
	ADD  R10, R19, R19
	MOVD R19, R12
	MOVD 16(R0), R10
	SUB  R10, R12, R12
	CMP  R21, R12
	BHS  prefetch_in_out_0
	ADD  R22, R12, R12

prefetch_in_out_0:
	PRFM (R12), PLDL1KEEP
	PRFM 64(R12), PLDL1KEEP
	MOVD 8(R0), R10
	ADD  R10, R19, R19

prefetch_skip_0:
	ADD  $24, R0, R11
	CMP  R20, R11
	BHS  prefetch_skip_1
	MOVD 24(R0), R10
	ADD  R10, R19, R19
	MOVD R19, R12
	MOVD 40(R0), R10
	SUB  R10, R12, R12
	CMP  R21, R12
	BHS  prefetch_in_out_1
	ADD  R22, R12, R12

