	MOVHU (R13), R10
	MOVBU 2(R13), R16
	BFI   $0, R16, $8, R11
	MOVH  R10, (R3)
	MOVB  R11, 2(R3)
	ADD   R12, R13, R13
	ADD   R12, R3, R3
	JMP   copy_4_end

copy_4_move_4through7:
	MOVWU (R13), R10
	ADD   R12, R13, R15
	MOVWU -4(R15), R11
	MOVW  R10, (R3)
	ADD   R12, R3, R15
	MOVW  R11, -4(R15)
	ADD   R12, R13, R13
	ADD   R12, R3, R3
	JMP   copy_4_end

copy_4_move_8through16:
	MOVD (R13), R10
	ADD  R12, R13, R15
	MOVD -8(R15), R11
	MOVD R10, (R3)
	ADD  R12, R3, R15
	MOVD R11, -8(R15)
	ADD  R12, R13, R13
	ADD  R12, R3, R3

copy_4_end:
	ADD R12, R6, R6
	ADD $0x18, R0, R0
	ADD $1, R2, R2
	CMP R1, R2
	BLO main_loop
	JMP loop_finished

copy_all_from_history:
	MOVD R10, R14
	SUBS $0x10, R14, R14
	BLO  copy_5_small

copy_5_loop:
	FMOVQ (R13), F0
	FMOVQ F0, (R3)
	ADD   $0x10, R13, R13
	ADD   $0x10, R3, R3
	SUBS  $0x10, R14, R14
	BHS   copy_5_loop
	ADD   R14, R13, R13
	ADD   $16, R13, R13
	ADD   R14, R3, R3
	ADD   $16, R3, R3
	FMOVQ -16(R13), F0
	FMOVQ F0, -16(R3)
	JMP   copy_5_end

copy_5_small:
	CMP $0x03, R10
	BEQ copy_5_move_3
	BLO copy_5_move_1or2
	CMP $0x08, R10
	BLO copy_5_move_4through7
	JMP copy_5_move_8through16

copy_5_move_1or2:
	MOVBU (R13), R16
	BFI   $0, R16, $8, R14
	ADD   R10, R13, R15
	MOVBU -1(R15), R16
	BFI   $0, R16, $8, R4
	MOVB  R14, (R3)
	ADD   R10, R3, R15
	MOVB  R4, -1(R15)
	ADD   R10, R13, R13
	ADD   R10, R3, R3
	JMP   copy_5_end

copy_5_move_3:
	MOVHU (R13), R14
	MOVBU 2(R13), R16
	BFI   $0, R16, $8, R4
	MOVH  R14, (R3)
	MOVB  R4, 2(R3)
	ADD   R10, R13, R13
	ADD   R10, R3, R3
	JMP   copy_5_end

copy_5_move_4through7:
	MOVWU (R13), R14
	ADD   R10, R13, R15
	MOVWU -4(R15), R4
	MOVW  R14, (R3)
	ADD   R10, R3, R15
	MOVW  R4, -4(R15)
	ADD   R10, R13, R13
	ADD   R10, R3, R3
	JMP   copy_5_end

copy_5_move_8through16:
	MOVD (R13), R14
	ADD  R10, R13, R15
	MOVD -8(R15), R4
	MOVD R14, (R3)
	ADD  R10, R3, R15
	MOVD R4, -8(R15)
	ADD  R10, R13, R13
	ADD  R10, R3, R3

copy_5_end:
	ADD R10, R6, R6
	SUB R10, R12, R12

	// Copy match from the current buffer
copy_match:
	MOVD R3, R10
	SUB  R11, R10, R10

	// ml <= mo
	CMP R11, R12
	BHI copy_overlapping_match

	// Copy non-overlapping match
	ADD  R12, R6, R6
	MOVD R12, R11
	SUBS $0x10, R11, R11
	BLO  copy_2_small

copy_2_loop:
	FMOVQ (R10), F0
	FMOVQ F0, (R3)
	ADD   $0x10, R10, R10
	ADD   $0x10, R3, R3
	SUBS  $0x10, R11, R11
	BHS   copy_2_loop
	ADD   R11, R10, R10
	ADD   $16, R10, R10
	ADD   R11, R3, R3
	ADD   $16, R3, R3
	FMOVQ -16(R10), F0
	FMOVQ F0, -16(R3)
	JMP   copy_2_end

copy_2_small:
	CMP $0x03, R12
	BEQ copy_2_move_3
	BLO copy_2_move_1or2
	CMP $0x08, R12
	BLO copy_2_move_4through7
	JMP copy_2_move_8through16

copy_2_move_1or2:
	MOVBU (R10), R16
	BFI   $0, R16, $8, R11
	ADD   R12, R10, R15
	MOVBU -1(R15), R16
	BFI   $0, R16, $8, R13
	MOVB  R11, (R3)
	ADD   R12, R3, R15
	MOVB  R13, -1(R15)
	ADD   R12, R10, R10
	ADD   R12, R3, R3
	JMP   copy_2_end

copy_2_move_3:
	MOVHU (R10), R11
	MOVBU 2(R10), R16
	BFI   $0, R16, $8, R13
	MOVH  R11, (R3)
	MOVB  R13, 2(R3)
	ADD   R12, R10, R10
	ADD   R12, R3, R3
	JMP   copy_2_end

copy_2_move_4through7:
	MOVWU (R10), R11
	ADD   R12, R10, R15
	MOVWU -4(R15), R13
	MOVW  R11, (R3)
	ADD   R12, R3, R15
	MOVW  R13, -4(R15)
	ADD   R12, R10, R10
	ADD   R12, R3, R3
	JMP   copy_2_end

copy_2_move_8through16:
	MOVD (R10), R11
	ADD  R12, R10, R15
	MOVD -8(R15), R13
	MOVD R11, (R3)
	ADD  R12, R3, R15
	MOVD R13, -8(R15)
	ADD  R12, R10, R10
	ADD  R12, R3, R3

copy_2_end:
	JMP handle_loop

	// Copy overlapping match
copy_overlapping_match:
	ADD R12, R6, R6
	CMP $0x10, R11
	BLO copy_slow_3

copy_3_blocks:
	FMOVQ (R10), F0
	FMOVQ F0, (R3)
	ADD   $0x10, R10, R10
	ADD   $0x10, R3, R3
	SUB   $0x10, R12, R12
	CMP   $0x10, R12
	BHS   copy_3_blocks
	TST   R12, R12
	BEQ   handle_loop

copy_slow_3:
	MOVBU (R10), R11
	MOVB  R11, (R3)
	ADD   $1, R10, R10
	ADD   $1, R3, R3
	SUBS  $1, R12, R12
	BNE   copy_slow_3

handle_loop:
	ADD $0x18, R0, R0
	ADD $1, R2, R2
	CMP R1, R2
	BLO main_loop

loop_finished:
	// Return value
	MOVD $0x01, R16
	MOVB R16, ret+8(FP)

	// Update the context
	MOVD ctx+0(FP), R0
	MOVD R2, 24(R0)
	MOVD R6, 104(R0)
	MOVD 80(R0), R16
	SUB  R16, R5, R5
	MOVD R5, 112(R0)
	RET

error_match_off_too_big:
	// Return value
	MOVD $0x00, R16
	MOVB R16, ret+8(FP)

	// Update the context
	MOVD ctx+0(FP), R0
	MOVD R2, 24(R0)
	MOVD R6, 104(R0)
	MOVD 80(R0), R16
	SUB  R16, R5, R5
	MOVD R5, 112(R0)
	RET

empty_seqs:
	// Return value
	MOVD $0x01, R16
	MOVB R16, ret+8(FP)
	RET

// func sequenceDecs_decodeSync_amd64(s *sequenceDecs, br *bitReader, ctx *decodeSyncAsmContext) int
// Requires: CMOV, SSE
TEXT ·sequenceDecs_decodeSync_arm64(SB), $96-32
	MOVD  br+8(FP), R1
	MOVD  24(R1), R2
	MOVBU 40(R1), R3
	MOVD  (R1), R22
	MOVD  32(R1), R5
	ADD   R5, R22, R22
	MOVD  ctx+16(FP), R25
	MOVD  72(R25), R6
	MOVD  80(R25), R7
	MOVD  88(R25), R8
	MOVD  (R25), R17
	MOVD  24(R25), R1
	MOVD  R1, 24(RSP)
	MOVD  48(R25), R1
	MOVD  R1, 32(RSP)
	MOVD  96(R25), R23
	MOVD  $0, R20
	MOVD  R20, R21
	MOVD  R20, R19
	MOVD  112(R25), R9
	MOVD  128(R25), R24
	MOVD  144(R25), R10
	MOVD  136(R25), R11
	MOVD  200(R25), R1
	MOVD  R1, 96(RSP)
	MOVD  176(R25), R26
	MOVD  184(R25), R25
	ADD   R25, R26, R26

	// Calculate pointer to s.out[cap(s.out)] (a past-end pointer)
	ADD R9, R24, R24

	// outBase += outPosition
	ADD     R11, R9, R9
	PCALIGN $0x40

sequenceDecs_decodeSync_amd64_main_loop:
	// Fill bitreader to have enough for the offset and match length.
	CMP  $0x08, R5
	BLT  sequenceDecs_decodeSync_amd64_fill_byte_by_byte
	LSR  $0x03, R3, R0
	SUB  R0, R22, R22
	MOVD (R22), R2
	SUB  R0, R5, R5
	AND  $0x07, R3, R3
	JMP  sequenceDecs_decodeSync_amd64_fill_end

sequenceDecs_decodeSync_amd64_fill_byte_by_byte:
	CMP   $0x00, R5
	BLE   sequenceDecs_decodeSync_amd64_fill_check_overread
	CMP   $0x07, R3
	BLE   sequenceDecs_decodeSync_amd64_fill_end
	LSL   $0x08, R2, R2
	SUB   $0x01, R22, R22
	SUB   $0x01, R5, R5
	SUB   $0x08, R3, R3
	MOVBU (R22), R0
	ORR   R0, R2, R2
	JMP   sequenceDecs_decodeSync_amd64_fill_byte_by_byte

sequenceDecs_decodeSync_amd64_fill_check_overread:
	CMP $0x40, R3
	BHI error_overread

sequenceDecs_decodeSync_amd64_fill_end:
	// Update offset
	MOVD R8, R0
	LSL  R3, R2, R13
	LSR  $0x01, R13, R13
	UBFX $8, R0, $8, R1
	LSR  $0x20, R0, R0
	ADD  R1, R3, R3
	EOR  $0x3f, R1, R1
	LSR  R1, R13, R13
	ADD  R13, R0, R0
	MOVD R0, R20

	// Update match length
	MOVD R7, R0
	LSL  R3, R2, R13
	LSR  $0x01, R13, R13
	UBFX $8, R0, $8, R1
	LSR  $0x20, R0, R0
	ADD  R1, R3, R3
	EOR  $0x3f, R1, R1
	LSR  R1, R13, R13
	ADD  R13, R0, R0
	MOVD R0, R21

	// Fill bitreader to have enough for the remaining
	CMP  $0x08, R5
	BLT  sequenceDecs_decodeSync_amd64_fill_2_byte_by_byte
	LSR  $0x03, R3, R0
	SUB  R0, R22, R22
	MOVD (R22), R2
	SUB  R0, R5, R5
	AND  $0x07, R3, R3
	JMP  sequenceDecs_decodeSync_amd64_fill_2_end

sequenceDecs_decodeSync_amd64_fill_2_byte_by_byte:
	CMP   $0x00, R5
	BLE   sequenceDecs_decodeSync_amd64_fill_2_check_overread
	CMP   $0x07, R3
	BLE   sequenceDecs_decodeSync_amd64_fill_2_end
	LSL   $0x08, R2, R2
	SUB   $0x01, R22, R22
	SUB   $0x01, R5, R5
	SUB   $0x08, R3, R3
	MOVBU (R22), R0
	ORR   R0, R2, R2
	JMP   sequenceDecs_decodeSync_amd64_fill_2_byte_by_byte

sequenceDecs_decodeSync_amd64_fill_2_check_overread:
	CMP $0x40, R3
	BHI error_overread

sequenceDecs_decodeSync_amd64_fill_2_end:
	// Update literal length
	MOVD R6, R0
	LSL  R3, R2, R13
	LSR  $0x01, R13, R13
	UBFX $8, R0, $8, R1
	LSR  $0x20, R0, R0
	ADD  R1, R3, R3
	EOR  $0x3f, R1, R1
	LSR  R1, R13, R13
	ADD  R13, R0, R0
	MOVD R0, R19

	// Fill bitreader for state updates
	UBFX $8, R8, $8, R0
	CMP  $0x00, R23
	BEQ  sequenceDecs_decodeSync_amd64_skip_update

	// Update Literal Length State
	MOVBU R6, R12
	LSRW  $0x10, R6, R6
	LSL   R3, R2, R13
	LSR   $0x01, R13, R13
	ADD   R12, R3, R3
	EOR   $0x3f, R12, R12
	LSR   R12, R13, R13
	ADD   R13, R6, R6

	// Load ctx.llTable
	MOVD (R17)(R6<<3), R6

	// Update Match Length State
	MOVBU R7, R12
	LSRW  $0x10, R7, R7
	LSL   R3, R2, R13
	LSR   $0x01, R13, R13
	ADD   R12, R3, R3
	EOR   $0x3f, R12, R12
	LSR   R12, R13, R13
	ADD   R13, R7, R7

	// Load ctx.mlTable
	MOVD 24(RSP), R1
	MOVD (R1)(R7<<3), R7

	// Update Offset State
	MOVBU R8, R12
	LSRW  $0x10, R8, R8
	LSL   R3, R2, R13
	LSR   $0x01, R13, R13
	ADD   R12, R3, R3
	EOR   $0x3f, R12, R12
	LSR   R12, R13, R13
	ADD   R13, R8, R8

	// Load ctx.ofTable
	MOVD 32(RSP), R1
	MOVD (R1)(R8<<3), R8

sequenceDecs_decodeSync_amd64_skip_update:
	// Adjust offset
	MOVD  s+0(FP), R1
	CMP   $0x01, R0
	BLS   sequenceDecs_decodeSync_amd64_adjust_offsetB_1_or_0
	FMOVQ 144(R1), F0
	MOVD  R20, 144(R1)
	FMOVQ F0, 152(R1)
	JMP   sequenceDecs_decodeSync_amd64_after_adjust

sequenceDecs_decodeSync_amd64_adjust_offsetB_1_or_0:
	CMP $0x00000000, R19
	BNE sequenceDecs_decodeSync_amd64_adjust_offset_maybezero
	ADD $1, R20, R20
	JMP sequenceDecs_decodeSync_amd64_adjust_offset_nonzero

sequenceDecs_decodeSync_amd64_adjust_offset_maybezero:
	TST  R20, R20
	BNE  sequenceDecs_decodeSync_amd64_adjust_offset_nonzero
	MOVD 144(R1), R20
	JMP  sequenceDecs_decodeSync_amd64_after_adjust

sequenceDecs_decodeSync_amd64_adjust_offset_nonzero:
	MOVD R20, R0
	MOVD $0, R13
	MOVD $-1, R14
	CMP  $0x03, R20
	CSEL EQ, R13, R0, R0
	CSEL EQ, R14, R13, R13
	ADD  R0<<3, R1, R15
	MOVD 144(R15), R16
	ADDS R16, R13, R13
	BNE  sequenceDecs_decodeSync_amd64_adjust_temp_valid
	MOVD $0x00000001, R13

sequenceDecs_decodeSync_amd64_adjust_temp_valid:
	CMP  $0x01, R20
	BEQ  sequenceDecs_decodeSync_amd64_adjust_skip
	MOVD 152(R1), R0
	MOVD R0, 160(R1)

sequenceDecs_decodeSync_amd64_adjust_skip:
	MOVD 144(R1), R0
	MOVD R0, 152(R1)
	MOVD R13, 144(R1)
	MOVD R13, R20

sequenceDecs_decodeSync_amd64_after_adjust:
	// Check values
	MOVD ctx+16(FP), R13
	MOVD 104(R13), R16
	SUBS R19, R16, R16
	MOVD R16, 104(R13)
	BMI  error_not_enough_literals
	CMP  $0x00020002, R21
	BHI  sequenceDecs_decodeSync_amd64_error_match_len_too_big
	TST  R20, R20
	BNE  sequenceDecs_decodeSync_amd64_match_len_ofs_ok
	TST  R21, R21
	BNE  sequenceDecs_decodeSync_amd64_error_match_len_ofs_mismatch

sequenceDecs_decodeSync_amd64_match_len_ofs_ok:
	// Check if we have enough space in s.out
	ADD R21, R19, R13
	ADD $32, R13, R13
	ADD R9, R13, R13
	CMP R24, R13
	BHI error_not_enough_space

	// Copy literals
	FMOVQ (R10), F0
	FMOVQ F0, (R9)
	CMP   $0x10, R19
	BLS   copy_1_end
	MOVD  $0x00000010, R13

copy_1:
	ADD   R13, R10, R15
	FMOVQ (R15), F0
	ADD   R13, R9, R15
	FMOVQ F0, (R15)
	ADD   $0x10, R13, R13
	CMP   R19, R13
	BLO   copy_1

copy_1_end:
	ADD R19, R10, R10
	ADD R19, R9, R9
	ADD R19, R11, R11

	// Malformed input if seq.mo > t+len(hist) || seq.mo > s.windowSize)
	MOVD R11, R1
	ADD  R25, R1, R1
	CMP  R1, R20
	BGT  error_match_off_too_big
	MOVD 96(RSP), R16
	CMP  R16, R20
	BGT  error_match_off_too_big

	// Copy match from history
	MOVD R20, R1
	SUBS R11, R1, R1
	BLS  copy_match
	MOVD R26, R13
	SUB  R1, R13, R13
	CMP  R1, R21
	BGT  copy_all_from_history
	MOVD R21, R1
	SUBS $0x10, R1, R1
	BLO  copy_4_small

copy_4_loop:
	FMOVQ (R13), F0
	FMOVQ F0, (R9)
	ADD   $0x10, R13, R13
	ADD   $0x10, R9, R9
	SUBS  $0x10, R1, R1
	BHS   copy_4_loop
	ADD   R1, R13, R13
	ADD   $16, R13, R13
	ADD   R1, R9, R9
	ADD   $16, R9, R9
	FMOVQ -16(R13), F0
	FMOVQ F0, -16(R9)
	JMP   copy_4_end

copy_4_small:
	CMP $0x03, R21
	BEQ copy_4_move_3
	CMP $0x08, R21
	BLO copy_4_move_4through7
	JMP copy_4_move_8through16

copy_4_move_3:
	MOVHU (R13), R1
	MOVBU 2(R13), R16
	BFI   $0, R16, $8, R20
	MOVH  R1, (R9)
	MOVB  R20, 2(R9)
	ADD   R21, R13, R13
	ADD   R21, R9, R9
	JMP   copy_4_end

copy_4_move_4through7:
	MOVWU (R13), R1
	ADD   R21, R13, R15
	MOVWU -4(R15), R12
	MOVW  R1, (R9)
	ADD   R21, R9, R15
	MOVW  R12, -4(R15)
	ADD   R21, R13, R13
	ADD   R21, R9, R9
	JMP   copy_4_end

copy_4_move_8through16:
	MOVD (R13), R1
	ADD  R21, R13, R15
	MOVD -8(R15), R12
	MOVD R1, (R9)
	ADD  R21, R9, R15
	MOVD R12, -8(R15)
	ADD  R21, R13, R13
	ADD  R21, R9, R9

copy_4_end:
	ADD R21, R11, R11
	JMP handle_loop
	JMP loop_finished

copy_all_from_history:
	MOVD R1, R14
	SUBS $0x10, R14, R14
	BLO  copy_5_small

copy_5_loop:
	FMOVQ (R13), F0
	FMOVQ F0, (R9)
	ADD   $0x10, R13, R13
	ADD   $0x10, R9, R9
	SUBS  $0x10, R14, R14
	BHS   copy_5_loop
	ADD   R14, R13, R13
	ADD   $16, R13, R13
	ADD   R14, R9, R9
	ADD   $16, R9, R9
	FMOVQ -16(R13), F0
	FMOVQ F0, -16(R9)
	JMP   copy_5_end

copy_5_small:
	CMP $0x03, R1
	BEQ copy_5_move_3
	BLO copy_5_move_1or2
	CMP $0x08, R1
	BLO copy_5_move_4through7
	JMP copy_5_move_8through16

copy_5_move_1or2:
	MOVBU (R13), R16
	BFI   $0, R16, $8, R14
	ADD   R1, R13, R15
	MOVBU -1(R15), R16
	BFI   $0, R16, $8, R4
	MOVB  R14, (R9)
	ADD   R1, R9, R15
	MOVB  R4, -1(R15)
	ADD   R1, R13, R13
	ADD   R1, R9, R9
	JMP   copy_5_end

copy_5_move_3:
	MOVHU (R13), R14
	MOVBU 2(R13), R16
	BFI   $0, R16, $8, R4
	MOVH  R14, (R9)
	MOVB  R4, 2(R9)
	ADD   R1, R13, R13
	ADD   R1, R9, R9
	JMP   copy_5_end

copy_5_move_4through7:
	MOVWU (R13), R14
	ADD   R1, R13, R15
	MOVWU -4(R15), R4
	MOVW  R14, (R9)
	ADD   R1, R9, R15
	MOVW  R4, -4(R15)
	ADD   R1, R13, R13
	ADD   R1, R9, R9
	JMP   copy_5_end

copy_5_move_8through16:
	MOVD (R13), R14
	ADD  R1, R13, R15
	MOVD -8(R15), R4
	MOVD R14, (R9)
	ADD  R1, R9, R15
	MOVD R4, -8(R15)
	ADD  R1, R13, R13
	ADD  R1, R9, R9

copy_5_end:
	ADD R1, R11, R11
	SUB R1, R21, R21

	// Copy match from the current buffer
copy_match:
	MOVD R9, R1
	SUB  R20, R1, R1

	// ml <= mo
	CMP R20, R21
	BHI copy_overlapping_match

	// Copy non-overlapping match
	ADD   R21, R11, R11
	FLDPQ (R1), (F0, F1)
	FSTPQ (F0, F1), (R9)
	CMP   $0x20, R21
	BHI   copy_2_long
	ADD   R21, R9, R9
	JMP   handle_loop

copy_2_long:
	ADD $32, R9, R12
	ADD R21, R9, R9
	ADD $0x20, R1, R1
	SUB $0x20, R21, R21

copy_2:
	FLDPQ (R1), (F0, F1)
	FSTPQ (F0, F1), (R12)
	ADD   $0x20, R1, R1
	ADD   $0x20, R12, R12
	SUBS  $0x20, R21, R21
	BHI   copy_2
	JMP   handle_loop

	// Copy overlapping match
copy_overlapping_match:
	ADD  R21, R11, R11
	CMP  $0x10, R20
	BLO  copy_slow_3
	MOVD R9, R12
	ADD  R21, R9, R9

copy_3:
	FMOVQ (R1), F0
	FMOVQ F0, (R12)
	ADD   $0x10, R1, R1
	ADD   $0x10, R12, R12
	SUBS  $0x10, R21, R21
	BHI   copy_3
	JMP   handle_loop

copy_slow_3:
	MOVBU (R1), R12
	MOVB  R12, (R9)
	ADD   $1, R1, R1
	ADD   $1, R9, R9
	SUBS  $1, R21, R21
	BNE   copy_slow_3

handle_loop:
	SUBS $1, R23, R23
	BPL  sequenceDecs_decodeSync_amd64_main_loop

loop_finished:
	MOVD br+8(FP), R0
	MOVD R2, 24(R0)
	MOVB R3, 40(R0)
	MOVD R5, 32(R0)

	// s.seqSize += outPosition - ctx.outPosition
	MOVD ctx+16(FP), R0
	MOVD s+0(FP), R1
	MOVD R11, R2
	MOVD 136(R0), R16
	SUB  R16, R2, R2
	MOVD 256(R1), R16
	ADD  R2, R16, R16
	MOVD R16, 256(R1)

	// Update the context
	MOVD ctx+16(FP), R0
	MOVD R11, 136(R0)
	MOVD 144(R0), R1
	SUB  R1, R10, R10
	MOVD R10, 168(R0)

	// Return success
	MOVD $0x00000000, R16
	MOVD R16, ret+24(FP)
	RET

	// Return with match length error
sequenceDecs_decodeSync_amd64_error_match_len_ofs_mismatch:
	MOVD ctx+16(FP), R1
	MOVD R21, 216(R1)
	MOVD $0x00000001, R16
	MOVD R16, ret+24(FP)
	RET

	// Return with match too long error
sequenceDecs_decodeSync_amd64_error_match_len_too_big:
	MOVD ctx+16(FP), R0
	MOVD R21, 216(R0)
	MOVD $0x00000002, R16
	MOVD R16, ret+24(FP)
	RET

	// Return with match offset too long error
error_match_off_too_big:
	MOVD ctx+16(FP), R0
	MOVD R20, 224(R0)
	MOVD R11, 136(R0)
	MOVD $0x00000003, R16
	MOVD R16, ret+24(FP)
	RET

	// Return with not enough literals error
error_not_enough_literals:
	MOVD ctx+16(FP), R0
	MOVD R19, 208(R0)
	MOVD $0x00000004, R16
	MOVD R16, ret+24(FP)
	RET

	// Return with overread error
error_overread:
	MOVD $0x00000006, R16
	MOVD R16, ret+24(FP)
	RET

	// Return with not enough output space error
error_not_enough_space:
	MOVD ctx+16(FP), R0
	MOVD R19, 208(R0)
	MOVD R21, 216(R0)
	MOVD R11, 136(R0)
	MOVD $0x00000005, R16
	MOVD R16, ret+24(FP)
	RET

// skipped sequenceDecs_decodeSync_bmi2 (generic twin preferred on arm64)

// func sequenceDecs_decodeSync_safe_amd64(s *sequenceDecs, br *bitReader, ctx *decodeSyncAsmContext) int
// Requires: CMOV, SSE
TEXT ·sequenceDecs_decodeSync_safe_arm64(SB), $96-32
	MOVD  br+8(FP), R1
	MOVD  24(R1), R2
	MOVBU 40(R1), R3
	MOVD  (R1), R22
	MOVD  32(R1), R5
	ADD   R5, R22, R22
	MOVD  ctx+16(FP), R25
	MOVD  72(R25), R6
	MOVD  80(R25), R7
	MOVD  88(R25), R8
	MOVD  (R25), R17
	MOVD  24(R25), R1
	MOVD  R1, 24(RSP)
	MOVD  48(R25), R1
	MOVD  R1, 32(RSP)
	MOVD  96(R25), R23
	MOVD  $0, R20
	MOVD  R20, R21
	MOVD  R20, R19
	MOVD  112(R25), R9
	MOVD  128(R25), R24
	MOVD  144(R25), R10
	MOVD  136(R25), R11
	MOVD  200(R25), R1
	MOVD  R1, 96(RSP)
	MOVD  176(R25), R26
	MOVD  184(R25), R25
	ADD   R25, R26, R26

	// Calculate pointer to s.out[cap(s.out)] (a past-end pointer)
	ADD R9, R24, R24

	// outBase += outPosition
	ADD     R11, R9, R9
	PCALIGN $0x40

sequenceDecs_decodeSync_safe_amd64_main_loop:
	// Fill bitreader to have enough for the offset and match length.
	CMP  $0x08, R5
	BLT  sequenceDecs_decodeSync_safe_amd64_fill_byte_by_byte
	LSR  $0x03, R3, R0
	SUB  R0, R22, R22
	MOVD (R22), R2
	SUB  R0, R5, R5
	AND  $0x07, R3, R3
	JMP  sequenceDecs_decodeSync_safe_amd64_fill_end

sequenceDecs_decodeSync_safe_amd64_fill_byte_by_byte:
	CMP   $0x00, R5
	BLE   sequenceDecs_decodeSync_safe_amd64_fill_check_overread
	CMP   $0x07, R3
	BLE   sequenceDecs_decodeSync_safe_amd64_fill_end
	LSL   $0x08, R2, R2
	SUB   $0x01, R22, R22
	SUB   $0x01, R5, R5
	SUB   $0x08, R3, R3
	MOVBU (R22), R0
	ORR   R0, R2, R2
	JMP   sequenceDecs_decodeSync_safe_amd64_fill_byte_by_byte

sequenceDecs_decodeSync_safe_amd64_fill_check_overread:
	CMP $0x40, R3
	BHI error_overread

sequenceDecs_decodeSync_safe_amd64_fill_end:
	// Update offset
	MOVD R8, R0
	LSL  R3, R2, R13
	LSR  $0x01, R13, R13
	UBFX $8, R0, $8, R1
	LSR  $0x20, R0, R0
	ADD  R1, R3, R3
	EOR  $0x3f, R1, R1
	LSR  R1, R13, R13
	ADD  R13, R0, R0
	MOVD R0, R20

	// Update match length
	MOVD R7, R0
	LSL  R3, R2, R13
	LSR  $0x01, R13, R13
	UBFX $8, R0, $8, R1
	LSR  $0x20, R0, R0
	ADD  R1, R3, R3
	EOR  $0x3f, R1, R1
	LSR  R1, R13, R13
	ADD  R13, R0, R0
	MOVD R0, R21

	// Fill bitreader to have enough for the remaining
	CMP  $0x08, R5
	BLT  sequenceDecs_decodeSync_safe_amd64_fill_2_byte_by_byte
	LSR  $0x03, R3, R0
	SUB  R0, R22, R22
	MOVD (R22), R2
	SUB  R0, R5, R5
	AND  $0x07, R3, R3
	JMP  sequenceDecs_decodeSync_safe_amd64_fill_2_end

sequenceDecs_decodeSync_safe_amd64_fill_2_byte_by_byte:
	CMP   $0x00, R5
	BLE   sequenceDecs_decodeSync_safe_amd64_fill_2_check_overread
	CMP   $0x07, R3
	BLE   sequenceDecs_decodeSync_safe_amd64_fill_2_end
	LSL   $0x08, R2, R2
	SUB   $0x01, R22, R22
	SUB   $0x01, R5, R5
	SUB   $0x08, R3, R3
	MOVBU (R22), R0
	ORR   R0, R2, R2
	JMP   sequenceDecs_decodeSync_safe_amd64_fill_2_byte_by_byte

sequenceDecs_decodeSync_safe_amd64_fill_2_check_overread:
	CMP $0x40, R3
	BHI error_overread

sequenceDecs_decodeSync_safe_amd64_fill_2_end:
	// Update literal length
	MOVD R6, R0
	LSL  R3, R2, R13
	LSR  $0x01, R13, R13
	UBFX $8, R0, $8, R1
	LSR  $0x20, R0, R0
	ADD  R1, R3, R3
	EOR  $0x3f, R1, R1
	LSR  R1, R13, R13
	ADD  R13, R0, R0
	MOVD R0, R19

	// Fill bitreader for state updates
	UBFX $8, R8, $8, R0
	CMP  $0x00, R23
	BEQ  sequenceDecs_decodeSync_safe_amd64_skip_update

	// Update Literal Length State
	MOVBU R6, R12
	LSRW  $0x10, R6, R6
	LSL   R3, R2, R13
	LSR   $0x01, R13, R13
	ADD   R12, R3, R3
	EOR   $0x3f, R12, R12
	LSR   R12, R13, R13
	ADD   R13, R6, R6

	// Load ctx.llTable
	MOVD (R17)(R6<<3), R6

	// Update Match Length State
	MOVBU R7, R12
	LSRW  $0x10, R7, R7
	LSL   R3, R2, R13
	LSR   $0x01, R13, R13
	ADD   R12, R3, R3
	EOR   $0x3f, R12, R12
	LSR   R12, R13, R13
	ADD   R13, R7, R7

	// Load ctx.mlTable
	MOVD 24(RSP), R1
	MOVD (R1)(R7<<3), R7

	// Update Offset State
	MOVBU R8, R12
	LSRW  $0x10, R8, R8
	LSL   R3, R2, R13
	LSR   $0x01, R13, R13
	ADD   R12, R3, R3
	EOR   $0x3f, R12, R12
	LSR   R12, R13, R13
	ADD   R13, R8, R8

	// Load ctx.ofTable
	MOVD 32(RSP), R1
	MOVD (R1)(R8<<3), R8

sequenceDecs_decodeSync_safe_amd64_skip_update:
	// Adjust offset
	MOVD  s+0(FP), R1
	CMP   $0x01, R0
	BLS   sequenceDecs_decodeSync_safe_amd64_adjust_offsetB_1_or_0
	FMOVQ 144(R1), F0
	MOVD  R20, 144(R1)
	FMOVQ F0, 152(R1)
	JMP   sequenceDecs_decodeSync_safe_amd64_after_adjust

sequenceDecs_decodeSync_safe_amd64_adjust_offsetB_1_or_0:
	CMP $0x00000000, R19
	BNE sequenceDecs_decodeSync_safe_amd64_adjust_offset_maybezero
	ADD $1, R20, R20
	JMP sequenceDecs_decodeSync_safe_amd64_adjust_offset_nonzero

sequenceDecs_decodeSync_safe_amd64_adjust_offset_maybezero:
	TST  R20, R20
	BNE  sequenceDecs_decodeSync_safe_amd64_adjust_offset_nonzero
	MOVD 144(R1), R20
	JMP  sequenceDecs_decodeSync_safe_amd64_after_adjust

sequenceDecs_decodeSync_safe_amd64_adjust_offset_nonzero:
	MOVD R20, R0
	MOVD $0, R13
	MOVD $-1, R14
	CMP  $0x03, R20
	CSEL EQ, R13, R0, R0
	CSEL EQ, R14, R13, R13
	ADD  R0<<3, R1, R15
	MOVD 144(R15), R16
	ADDS R16, R13, R13
	BNE  sequenceDecs_decodeSync_safe_amd64_adjust_temp_valid
	MOVD $0x00000001, R13

sequenceDecs_decodeSync_safe_amd64_adjust_temp_valid:
	CMP  $0x01, R20
	BEQ  sequenceDecs_decodeSync_safe_amd64_adjust_skip
	MOVD 152(R1), R0
	MOVD R0, 160(R1)

sequenceDecs_decodeSync_safe_amd64_adjust_skip:
	MOVD 144(R1), R0
	MOVD R0, 152(R1)
	MOVD R13, 144(R1)
	MOVD R13, R20

sequenceDecs_decodeSync_safe_amd64_after_adjust:
	// Check values
	MOVD ctx+16(FP), R13
	MOVD 104(R13), R16
	SUBS R19, R16, R16
	MOVD R16, 104(R13)
	BMI  error_not_enough_literals
	CMP  $0x00020002, R21
	BHI  sequenceDecs_decodeSync_safe_amd64_error_match_len_too_big
	TST  R20, R20
	BNE  sequenceDecs_decodeSync_safe_amd64_match_len_ofs_ok
	TST  R21, R21
	BNE  sequenceDecs_decodeSync_safe_amd64_error_match_len_ofs_mismatch

sequenceDecs_decodeSync_safe_amd64_match_len_ofs_ok:
	// Check if we have enough space in s.out
	ADD R21, R19, R13
	ADD R9, R13, R13
	CMP R24, R13
	BHI error_not_enough_space

	// Copy literals
	TST  R19, R19
	BEQ  check_offset
	MOVD R19, R13
	SUBS $0x10, R13, R13
	BLO  copy_1_small

copy_1_loop:
	FMOVQ (R10), F0
	FMOVQ F0, (R9)
	ADD   $0x10, R10, R10
	ADD   $0x10, R9, R9
	SUBS  $0x10, R13, R13
	BHS   copy_1_loop
	ADD   R13, R10, R10
	ADD   $16, R10, R10
	ADD   R13, R9, R9
	ADD   $16, R9, R9
	FMOVQ -16(R10), F0
	FMOVQ F0, -16(R9)
	JMP   copy_1_end

copy_1_small:
	CMP $0x03, R19
	BEQ copy_1_move_3
	BLO copy_1_move_1or2
	CMP $0x08, R19
	BLO copy_1_move_4through7
	JMP copy_1_move_8through16

copy_1_move_1or2:
	MOVBU (R10), R16
	BFI   $0, R16, $8, R13
	ADD   R19, R10, R15
	MOVBU -1(R15), R16
	BFI   $0, R16, $8, R14
	MOVB  R13, (R9)
	ADD   R19, R9, R15
	MOVB  R14, -1(R15)
	ADD   R19, R10, R10
	ADD   R19, R9, R9
	JMP   copy_1_end

copy_1_move_3:
	MOVHU (R10), R13
	MOVBU 2(R10), R16
	BFI   $0, R16, $8, R14
	MOVH  R13, (R9)
	MOVB  R14, 2(R9)
	ADD   R19, R10, R10
	ADD   R19, R9, R9
	JMP   copy_1_end

copy_1_move_4through7:
	MOVWU (R10), R13
	ADD   R19, R10, R15
	MOVWU -4(R15), R14
	MOVW  R13, (R9)
	ADD   R19, R9, R15
	MOVW  R14, -4(R15)
	ADD   R19, R10, R10
	ADD   R19, R9, R9
	JMP   copy_1_end

copy_1_move_8through16:
	MOVD (R10), R13
	ADD  R19, R10, R15
	MOVD -8(R15), R14
	MOVD R13, (R9)
	ADD  R19, R9, R15
	MOVD R14, -8(R15)
	ADD  R19, R10, R10
	ADD  R19, R9, R9

copy_1_end:
	ADD R19, R11, R11

	// Malformed input if seq.mo > t+len(hist) || seq.mo > s.windowSize)
check_offset:
	MOVD R11, R1
	ADD  R25, R1, R1
	CMP  R1, R20
	BGT  error_match_off_too_big
	MOVD 96(RSP), R16
	CMP  R16, R20
	BGT  error_match_off_too_big

	// Copy match from history
	MOVD R20, R1
	SUBS R11, R1, R1
	BLS  copy_match
	MOVD R26, R13
	SUB  R1, R13, R13
	CMP  R1, R21
	BGT  copy_all_from_history
	MOVD R21, R1
	SUBS $0x10, R1, R1
	BLO  copy_4_small

copy_4_loop:
	FMOVQ (R13), F0
	FMOVQ F0, (R9)
	ADD   $0x10, R13, R13
	ADD   $0x10, R9, R9
	SUBS  $0x10, R1, R1
	BHS   copy_4_loop
	ADD   R1, R13, R13
	ADD   $16, R13, R13
	ADD   R1, R9, R9
	ADD   $16, R9, R9
	FMOVQ -16(R13), F0
	FMOVQ F0, -16(R9)
	JMP   copy_4_end

copy_4_small:
	CMP $0x03, R21
	BEQ copy_4_move_3
	CMP $0x08, R21
	BLO copy_4_move_4through7
	JMP copy_4_move_8through16

copy_4_move_3:
	MOVHU (R13), R1
	MOVBU 2(R13), R16
	BFI   $0, R16, $8, R20
	MOVH  R1, (R9)
	MOVB  R20, 2(R9)
	ADD   R21, R13, R13
	ADD   R21, R9, R9
	JMP   copy_4_end

copy_4_move_4through7:
	MOVWU (R13), R1
	ADD   R21, R13, R15
	MOVWU -4(R15), R12
	MOVW  R1, (R9)
	ADD   R21, R9, R15
	MOVW  R12, -4(R15)
	ADD   R21, R13, R13
	ADD   R21, R9, R9
	JMP   copy_4_end

copy_4_move_8through16:
	MOVD (R13), R1
	ADD  R21, R13, R15
	MOVD -8(R15), R12
	MOVD R1, (R9)
	ADD  R21, R9, R15
	MOVD R12, -8(R15)
	ADD  R21, R13, R13
	ADD  R21, R9, R9

copy_4_end:
	ADD R21, R11, R11
	JMP handle_loop
	JMP loop_finished

copy_all_from_history:
	MOVD R1, R14
	SUBS $0x10, R14, R14
	BLO  copy_5_small

copy_5_loop:
	FMOVQ (R13), F0
	FMOVQ F0, (R9)
	ADD   $0x10, R13, R13
	ADD   $0x10, R9, R9
	SUBS  $0x10, R14, R14
	BHS   copy_5_loop
	ADD   R14, R13, R13
	ADD   $16, R13, R13
	ADD   R14, R9, R9
	ADD   $16, R9, R9
	FMOVQ -16(R13), F0
	FMOVQ F0, -16(R9)
	JMP   copy_5_end

copy_5_small:
	CMP $0x03, R1
	BEQ copy_5_move_3
	BLO copy_5_move_1or2
	CMP $0x08, R1
	BLO copy_5_move_4through7
	JMP copy_5_move_8through16

copy_5_move_1or2:
	MOVBU (R13), R16
	BFI   $0, R16, $8, R14
	ADD   R1, R13, R15
	MOVBU -1(R15), R16
	BFI   $0, R16, $8, R4
	MOVB  R14, (R9)
	ADD   R1, R9, R15
	MOVB  R4, -1(R15)
	ADD   R1, R13, R13
	ADD   R1, R9, R9
	JMP   copy_5_end

copy_5_move_3:
	MOVHU (R13), R14
	MOVBU 2(R13), R16
	BFI   $0, R16, $8, R4
	MOVH  R14, (R9)
	MOVB  R4, 2(R9)
	ADD   R1, R13, R13
	ADD   R1, R9, R9
	JMP   copy_5_end

copy_5_move_4through7:
	MOVWU (R13), R14
	ADD   R1, R13, R15
	MOVWU -4(R15), R4
	MOVW  R14, (R9)
	ADD   R1, R9, R15
	MOVW  R4, -4(R15)
	ADD   R1, R13, R13
	ADD   R1, R9, R9
	JMP   copy_5_end

copy_5_move_8through16:
	MOVD (R13), R14
	ADD  R1, R13, R15
	MOVD -8(R15), R4
	MOVD R14, (R9)
	ADD  R1, R9, R15
	MOVD R4, -8(R15)
	ADD  R1, R13, R13
	ADD  R1, R9, R9

copy_5_end:
	ADD R1, R11, R11
	SUB R1, R21, R21

	// Copy match from the current buffer
copy_match:
	MOVD R9, R1
	SUB  R20, R1, R1

	// ml <= mo
	CMP R20, R21
	BHI copy_overlapping_match

	// Copy non-overlapping match
	ADD  R21, R11, R11
	MOVD R21, R12
	SUBS $0x10, R12, R12
	BLO  copy_2_small

copy_2_loop:
	FMOVQ (R1), F0
	FMOVQ F0, (R9)
	ADD   $0x10, R1, R1
	ADD   $0x10, R9, R9
	SUBS  $0x10, R12, R12
	BHS   copy_2_loop
	ADD   R12, R1, R1
	ADD   $16, R1, R1
	ADD   R12, R9, R9
	ADD   $16, R9, R9
	FMOVQ -16(R1), F0
	FMOVQ F0, -16(R9)
	JMP   copy_2_end

copy_2_small:
	CMP $0x03, R21
	BEQ copy_2_move_3
	BLO copy_2_move_1or2
	CMP $0x08, R21
	BLO copy_2_move_4through7
	JMP copy_2_move_8through16

copy_2_move_1or2:
	MOVBU (R1), R16
	BFI   $0, R16, $8, R12
	ADD   R21, R1, R15
	MOVBU -1(R15), R16
	BFI   $0, R16, $8, R13
	MOVB  R12, (R9)
	ADD   R21, R9, R15
	MOVB  R13, -1(R15)
	ADD   R21, R1, R1
	ADD   R21, R9, R9
	JMP   copy_2_end

copy_2_move_3:
	MOVHU (R1), R12
	MOVBU 2(R1), R16
	BFI   $0, R16, $8, R13
	MOVH  R12, (R9)
	MOVB  R13, 2(R9)
	ADD   R21, R1, R1
	ADD   R21, R9, R9
	JMP   copy_2_end

copy_2_move_4through7:
	MOVWU (R1), R12
	ADD   R21, R1, R15
	MOVWU -4(R15), R13
	MOVW  R12, (R9)
	ADD   R21, R9, R15
	MOVW  R13, -4(R15)
	ADD   R21, R1, R1
	ADD   R21, R9, R9
	JMP   copy_2_end

copy_2_move_8through16:
	MOVD (R1), R12
	ADD  R21, R1, R15
	MOVD -8(R15), R13
	MOVD R12, (R9)
	ADD  R21, R9, R15
	MOVD R13, -8(R15)
	ADD  R21, R1, R1
	ADD  R21, R9, R9

copy_2_end:
	JMP handle_loop

	// Copy overlapping match
copy_overlapping_match:
	ADD R21, R11, R11
	CMP $0x10, R20
	BLO copy_slow_3

copy_3_blocks:
	FMOVQ (R1), F0
	FMOVQ F0, (R9)
	ADD   $0x10, R1, R1
	ADD   $0x10, R9, R9
	SUB   $0x10, R21, R21
	CMP   $0x10, R21
	BHS   copy_3_blocks
	TST   R21, R21
	BEQ   handle_loop

copy_slow_3:
	MOVBU (R1), R12
	MOVB  R12, (R9)
	ADD   $1, R1, R1
	ADD   $1, R9, R9
	SUBS  $1, R21, R21
	BNE   copy_slow_3

handle_loop:
	SUBS $1, R23, R23
	BPL  sequenceDecs_decodeSync_safe_amd64_main_loop

loop_finished:
	MOVD br+8(FP), R0
	MOVD R2, 24(R0)
	MOVB R3, 40(R0)
	MOVD R5, 32(R0)

	// s.seqSize += outPosition - ctx.outPosition
	MOVD ctx+16(FP), R0
	MOVD s+0(FP), R1
	MOVD R11, R2
	MOVD 136(R0), R16
	SUB  R16, R2, R2
	MOVD 256(R1), R16
	ADD  R2, R16, R16
	MOVD R16, 256(R1)

	// Update the context
	MOVD ctx+16(FP), R0
	MOVD R11, 136(R0)
	MOVD 144(R0), R1
	SUB  R1, R10, R10
	MOVD R10, 168(R0)

	// Return success
	MOVD $0x00000000, R16
	MOVD R16, ret+24(FP)
	RET

	// Return with match length error
sequenceDecs_decodeSync_safe_amd64_error_match_len_ofs_mismatch:
	MOVD ctx+16(FP), R1
	MOVD R21, 216(R1)
	MOVD $0x00000001, R16
	MOVD R16, ret+24(FP)
	RET

	// Return with match too long error
sequenceDecs_decodeSync_safe_amd64_error_match_len_too_big:
	MOVD ctx+16(FP), R0
	MOVD R21, 216(R0)
	MOVD $0x00000002, R16
	MOVD R16, ret+24(FP)
	RET

	// Return with match offset too long error
error_match_off_too_big:
	MOVD ctx+16(FP), R0
	MOVD R20, 224(R0)
	MOVD R11, 136(R0)
	MOVD $0x00000003, R16
	MOVD R16, ret+24(FP)
	RET

	// Return with not enough literals error
error_not_enough_literals:
	MOVD ctx+16(FP), R0
	MOVD R19, 208(R0)
	MOVD $0x00000004, R16
	MOVD R16, ret+24(FP)
	RET

	// Return with overread error
error_overread:
	MOVD $0x00000006, R16
	MOVD R16, ret+24(FP)
	RET

	// Return with not enough output space error
error_not_enough_space:
	MOVD ctx+16(FP), R0
	MOVD R19, 208(R0)
	MOVD R21, 216(R0)
	MOVD R11, 136(R0)
	MOVD $0x00000005, R16
	MOVD R16, ret+24(FP)
	RET

